// src/lib/k2FormGorselleri.ts
//
// K2 (Boşaltma Konulu Kontrol Dökümanı) formunun ORİJİNAL docx'ten
// LibreOffice ile birebir (tasarım, görseller, tablo hücre birleşimleri
// korunarak) PDF'e çevrilip 150 DPI PNG olarak dışa aktarılmış hâli —
// Belge Oluştur'daki K2 render edilirken her sayfa arka plan görseli
// olarak kullanılır (bkz. BelgeOlusturForm.tsx → renderYapilandirilmisBelge,
// K3 ile aynı yöntem).
//
// Bu dosya BelgeOlusturForm.tsx'ten DİNAMİK import edilir (await
// import(...)) — ana sayfa yükünü artırmasın diye, yalnızca K2 PDF'i
// üretilirken yüklenir.
//
// NOT: base64 verisi bilinçli olarak TEK SATIR (chunk'lanmamış) tutulur
// — çok sayıda "+" ile birleştirilmiş küçük parçalar, build sürecinde
// bir regex/AST işleminin aşırı yavaşlayıp bellek taşırmasına
// (RangeError: Maximum call stack size exceeded, OOM) yol açabiliyor
// (bkz. k3FormGorselleri.ts'teki aynı sorun ve çözümü).

export const K2_FORM_SAYFA1 =
  "data:image/png;base64,";

export const K2_FORM_SAYFA2 =
  "data:image/png;base64,";

